#!/usr/bin/env python3
"""
Script to reproduce the pdftk issue on Ubuntu
"""

import subprocess
import sys
from paper2remarkable.utils import check_pdftool
from paper2remarkable.exceptions import NoPDFToolError

def test_tool_detection():
    """Test the tool detection mechanism"""
    print("Testing PDF tool detection...")

    # Test with default paths
    try:
        tool = check_pdftool("pdftk", "qpdf")
        print(f"Detected tool: {tool}")
    except NoPDFToolError:
        print("No PDF tools detected")
    except Exception as e:
        print(f"Error during tool detection: {e}")

    # Test what tools are actually available
    print("\nChecking actual availability:")

    # Check if pdftk is available
    try:
        result = subprocess.run(["pdftk", "--version"], 
                              capture_output=True, timeout=5)
        print(f"pdftk available: {result.returncode == 0}")
        if result.returncode == 0:
            print(f"pdftk output: {result.stdout.decode()[:100]}...")
    except FileNotFoundError:
        print("pdftk: command not found")
    except Exception as e:
        print(f"pdftk check error: {e}")

    # Check if qpdf is available  
    try:
        result = subprocess.run(["qpdf", "--version"], 
                              capture_output=True, timeout=5)
        print(f"qpdf available: {result.returncode == 0}")
        if result.returncode == 0:
            print(f"qpdf output: {result.stdout.decode()[:100]}...")
    except FileNotFoundError:
        print("qpdf: command not found")
    except Exception as e:
        print(f"qpdf check error: {e}")

if __name__ == "__main__":
    test_tool_detection()

